import { Link } from 'gatsby';
import React, { useEffect } from 'react';
import { Col, Container, Row } from 'react-bootstrap';
import { FaCheckCircle } from 'react-icons/fa';
import Navbar from '@/pages/single/home-9/components/Navbar';
import Footer from '@/pages/single/home-9/components/Footer';

const ThankYouPage = () => {
  useEffect(() => {
    // Track thankyou page view
    if (typeof window !== 'undefined' && window.gtag) {
      window.gtag('event', 'thankyou_page_view', {
        event_category: 'conversion',
        event_label: 'form_submission',
      });
    }

    // Facebook Pixel (if loaded)
    if (typeof window !== 'undefined' && (window as any).fbq) {
      (window as any).fbq('track', 'Lead', {
        content_name: 'thankyou_page',
      });
    }
  }, []);

  return (
    <>
      <Navbar />
      <div
        className="thankyou-area"
        style={{
          background: 'linear-gradient(180deg, #EFF6FF 0%, #FFFFFF 40%)',
          paddingTop: '80px',
          paddingBottom: '80px',
          minHeight: '60vh',
          display: 'flex',
          alignItems: 'center',
        }}
      >
        <Container>
          <Row className="justify-content-center">
            <Col lg={8} md={10} xs={12}>
              <div
                className="thankyou-content text-center"
              >
                {/* Check icon */}
                <div className="thankyou-icon mb-4">
                  <FaCheckCircle size={80} color="#1E40AF" />
                </div>

                {/* Heading */}
                <h1
                  style={{
                    color: '#1B2A57',
                    fontSize: 'clamp(28px, 5vw, 48px)',
                    fontWeight: 700,
                    lineHeight: 1.2,
                    marginBottom: '16px',
                  }}
                >
                  Cảm ơn bạn đã để lại thông tin!
                </h1>

                {/* Subtext */}
                <p
                  style={{
                    color: '#4B5563',
                    fontSize: 'clamp(16px, 2.5vw, 20px)',
                    lineHeight: 1.6,
                    maxWidth: '560px',
                    margin: '0 auto 40px',
                  }}
                >
                  Đội ngũ tư vấn của chúng tôi sẽ liên hệ với bạn trong{' '}
                  <strong style={{ color: '#1E40AF' }}>vòng 24h</strong>.
                </p>

                {/* Action buttons */}
                <div className="thankyou-actions d-flex flex-wrap gap-3 justify-content-center">
                  <Link
                    to="/#service"
                    className="theme-btn4"
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: '8px',
                    }}
                  >
                    Khám phá tính năng
                  </Link>
                  <Link
                    to="/"
                    className="theme-btn"
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: '8px',
                    }}
                  >
                    Về trang chủ
                  </Link>
                </div>
              </div>
            </Col>
          </Row>
        </Container>
      </div>
      <Footer />
    </>
  );
};

export default ThankYouPage;